import sys; sys.path.insert(0,'src')
import re
s=open('src/probes.py').read()
i=s.index('        m = re.search(r"-?\\d+(?:,\\d{3})*|[a-z]+(?:-[a-z]+)?", t.lower())'); j=s.index('        # fall back: first number or number-word anywhere')
s=s[:i]+s[j:].replace('        # fall back: first number or number-word anywhere','        # first number or number-word anywhere in the continuation',1)
s=s.replace('''    for v in sorted({c, n}):''','''    if max(a, b) >= 20:  # local grid around a multi-digit target
        for x in range(a - 3, a + 4):
            for y in range(b - 3, b + 4):
                if (x, y) not in ((a, b), (b, a)):
                    pr.append(P(f"gridl_{x}_{y}", "near", "grid_raw", 0, f"{x}+{y}=", "", "int", x + y, x=x, y=y))
    for v in sorted({c, n}):''')
open('src/probes.py','w').write(s)
import importlib, probes, time, torch
from common import *
model,tok=load("Qwen/Qwen2.5-1.5B-Instruct")
for t in ["2+2=","2+2=5"," 5"," four","17+25=42","The capital of France is Paris"]: print(repr(t),[tok.decode(i) for i in tok(t).input_ids])
for tg in ["add_2_2_5","add_17_25_43","cap_France_Rome","cap_Egypt_Baghdad","cap_England_Vienna","add_3_4_9"]:
    t0=time.time(); ps=ProbeSet(model,tok,tg); 
    import collections
    acc=collections.defaultdict(list)
    for p,ok in zip(ps.probes,ps.base_ok): acc[p['group']+'/'+p['sub']].append(ok)
    print(tg, round(time.time()-t0,1), {k:f"{sum(v)}/{len(v)}" for k,v in acc.items()})
    for p,g,ok in zip(ps.probes,ps.base_gen,ps.base_ok):
        if p['group'] in('exact','paraphrase','entail') and not ok: print("   MISS",repr(p['text'][:70]),p['orig'],repr(g))
    if tg=="add_2_2_5":
        for p,g in list(zip(ps.probes,ps.base_gen))[:60:6]: print("   ",repr(p['text'][:50]),repr(g))
    r=ps.evaluate(model); print("self-KL max",max(x['kl'] for x in r))
t0=time.time(); u=Unrelated(model,tok); print("unrel",time.time()-t0,len(u.cf_texts),u.wiki_test.shape,u.evaluate(model)); print(torch.cuda.memory_allocated()/1e9)
print(tok.decode(u.chat_ids[0]))
E

