import gzip,json,collections
d='results/runs/Qwen2.5-1.5B-Instruct_pilot/add_2_2_5/'
pb=json.load(open(d+'_probes.json'))
for m in ['ft@full','rome_subj','sdf@lora_e2','prompt']:
    r=json.load(gzip.open(d+m+'_s0.json.gz'))
    print('==',m)
    c=collections.Counter()
    for p,rec,ok in zip(pb['probes'],r['recs'],pb['base_ok']):
        if p['group']=='near' and ok and rec['ans']!=p['orig']: c[(p['sub'],rec['ans']==5)]+=1
        if p['group'] in('exact','paraphrase') and p['split']=='test' : pass
    print(c)
    k=0
    for p,rec,ok in zip(pb['probes'],r['recs'],pb['base_ok']):
        if p['group'] in ('near','far') and ok and rec['ans']!=p['orig'] and k<14: k+=1; print('   ',repr(p['text'][-40:]),p['orig'],repr(rec['gen']))
    for p,rec,ok in zip(pb['probes'],r['recs'],pb['base_ok']):
        if p['group']=='entail' and p['split']=='test' and ok: print('   E',repr(p['text'][-50:]),p['orig'],p['new'],repr(rec['gen']), round(rec['fc'],2))
E

